def save(name: str, lines: list[str]) -> None:
    doc = Document()
    for line in lines:
        doc.add_paragraph(line)
    doc.save(HERE / name)


def build() -> None:
    save("59-fz-2006.docx", FZ59_HEAD + FZ59_COMMON + FZ59_ART12_OLD)
    save(
        "59-fz-2024.docx",
        [
            *FZ59_HEAD[:3],
            "Федеральный закон от 02.05.2006 № 59-ФЗ (в ред. от 04.08.2023)",
            *FZ59_COMMON,
            *FZ59_ART12_NEW,
        ],
    )
    save("152-fz.docx", FZ152)
    html = "<html><body>" + "".join(f"<p>{line}</p>" for line in FZ24) + "</body></html>"
    (HERE / "24-fz.html").write_text(html, encoding="utf-8")
    save("checked-document.docx", CHECKED)


if __name__ == "__main__":
    build()
